=== FILE: apb_gpio.v ===
`timescale 1ns / 1ps
`default_nettype none

// apb_gpio: APB4 GPIO peripheral with interrupts.
// Implements interface_spec.md per microarchitecture.md.
//   - zero wait states, no state machine
//   - all registers 32 bits wide, pins >= N held at zero by PINS
//   - status <= (status & ~clear) | detected  (a detection beats a clear)
module apb_gpio #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer N          = 8
) (
    input  wire                  pclk,
    input  wire                  presetn,
    input  wire [ADDR_WIDTH-1:0] paddr,
    input  wire                  psel,
    input  wire                  penable,
    input  wire                  pwrite,
    input  wire [31:0]           pwdata,
    input  wire [3:0]            pstrb,
    output wire [31:0]           prdata,
    output wire                  pready,
    output wire                  pslverr,
    input  wire [N-1:0]          gpio_in,
    output wire [N-1:0]          gpio_out,
    output wire [N-1:0]          gpio_oe,
    output wire                  irq
);

    // Bits 0..N-1 set: the pins that exist.
    localparam [31:0] PINS = (N >= 32) ? 32'hFFFF_FFFF : ((32'h1 << N) - 32'h1);

    localparam [3:0] IDX_DATA_OUT    = 4'd0;
    localparam [3:0] IDX_DIR         = 4'd1;
    localparam [3:0] IDX_DATA_IN     = 4'd2;
    localparam [3:0] IDX_INTR_RISE   = 4'd3;
    localparam [3:0] IDX_INTR_FALL   = 4'd4;
    localparam [3:0] IDX_INTR_HIGH   = 4'd5;
    localparam [3:0] IDX_INTR_LOW    = 4'd6;
    localparam [3:0] IDX_INTR_ENABLE = 4'd7;
    localparam [3:0] IDX_INTR_STATUS = 4'd8;

    // ------------------------------------------------------------------
    // APB decode
    // ------------------------------------------------------------------
    wire       access = psel & penable;
    wire [3:0] index  = paddr[5:2];
    wire       upper_zero;

    generate
        if (ADDR_WIDTH > 6) begin : g_addr_hi
            assign upper_zero = ~|paddr[ADDR_WIDTH-1:6];
        end else begin : g_addr_nohi
            assign upper_zero = 1'b1;
        end
    endgenerate

    wire mapped = (paddr[1:0] == 2'b00) & upper_zero & (index <= IDX_INTR_STATUS);
    wire wr     = access & pwrite & mapped;
    wire rd     = access & ~pwrite & mapped;

    wire [31:0] wmask   = {{8{pstrb[3]}}, {8{pstrb[2]}}, {8{pstrb[1]}}, {8{pstrb[0]}}} & PINS;
    wire [31:0] wdata_m = pwdata & wmask;

    // ------------------------------------------------------------------
    // Input widening (zeros above N)
    // ------------------------------------------------------------------
    wire [31:0] gin_w;

    generate
        if (N < 32) begin : g_in_pad
            assign gin_w = {{(32-N){1'b0}}, gpio_in};
        end else begin : g_in_full
            assign gin_w = gpio_in;
        end
    endgenerate

    // ------------------------------------------------------------------
    // Registers
    // ------------------------------------------------------------------
    reg [31:0] data_out_q;
    reg [31:0] dir_q;
    reg [31:0] rise_en_q;
    reg [31:0] fall_en_q;
    reg [31:0] high_en_q;
    reg [31:0] low_en_q;
    reg [31:0] intr_en_q;
    reg [31:0] status_q;
    reg [31:0] in_q;
    reg [31:0] in_prev_q;

    // ------------------------------------------------------------------
    // Detection (combinational from the samples and the enables)
    // ------------------------------------------------------------------
    wire [31:0] rise_c   = in_q & ~in_prev_q;
    wire [31:0] fall_c   = ~in_q & in_prev_q;
    wire [31:0] detected = ((rise_c & rise_en_q) | (fall_c & fall_en_q)
                          | (in_q & high_en_q) | (~in_q & low_en_q)) & PINS;
    wire [31:0] clear    = (wr && (index == IDX_INTR_STATUS)) ? wdata_m : 32'd0;

    always @(posedge pclk) begin
        if (!presetn) begin
            data_out_q <= 32'd0;
            dir_q      <= 32'd0;
            rise_en_q  <= 32'd0;
            fall_en_q  <= 32'd0;
            high_en_q  <= 32'd0;
            low_en_q   <= 32'd0;
            intr_en_q  <= 32'd0;
            status_q   <= 32'd0;
            in_q       <= 32'd0;
            in_prev_q  <= 32'd0;
        end else begin
            if (wr && (index == IDX_DATA_OUT))
                data_out_q <= (data_out_q & ~wmask) | wdata_m;
            if (wr && (index == IDX_DIR))
                dir_q <= (dir_q & ~wmask) | wdata_m;
            if (wr && (index == IDX_INTR_RISE))
                rise_en_q <= (rise_en_q & ~wmask) | wdata_m;
            if (wr && (index == IDX_INTR_FALL))
                fall_en_q <= (fall_en_q & ~wmask) | wdata_m;
            if (wr && (index == IDX_INTR_HIGH))
                high_en_q <= (high_en_q & ~wmask) | wdata_m;
            if (wr && (index == IDX_INTR_LOW))
                low_en_q <= (low_en_q & ~wmask) | wdata_m;
            if (wr && (index == IDX_INTR_ENABLE))
                intr_en_q <= (intr_en_q & ~wmask) | wdata_m;

            in_q      <= gin_w;
            in_prev_q <= in_q;
            status_q  <= (status_q & ~clear) | detected;
        end
    end

    // ------------------------------------------------------------------
    // Read multiplexer and responses
    // ------------------------------------------------------------------
    reg [31:0] rmux;

    always @(*) begin
        case (index)
            IDX_DATA_OUT:    rmux = data_out_q;
            IDX_DIR:         rmux = dir_q;
            IDX_DATA_IN:     rmux = in_q;
            IDX_INTR_RISE:   rmux = rise_en_q;
            IDX_INTR_FALL:   rmux = fall_en_q;
            IDX_INTR_HIGH:   rmux = high_en_q;
            IDX_INTR_LOW:    rmux = low_en_q;
            IDX_INTR_ENABLE: rmux = intr_en_q;
            IDX_INTR_STATUS: rmux = status_q;
            default:         rmux = 32'd0;
        endcase
    end

    assign prdata   = rd ? rmux : 32'd0;
    assign pready   = 1'b1;
    assign pslverr  = access & (~mapped | (pwrite & (index == IDX_DATA_IN)));
    assign gpio_out = data_out_q[N-1:0];
    assign gpio_oe  = dir_q[N-1:0];
    assign irq      = |(status_q & intr_en_q);

`ifdef FORMAL
    // Design-intent assertions (not a full proof).
    reg f_reset_seen = 1'b0;
    always @(posedge pclk) begin
        if (!presetn)
            f_reset_seen <= 1'b1;
    end

    always @(*) begin
        assert (pready == 1'b1);
        if (!access) begin
            assert (prdata == 32'd0);
            assert (pslverr == 1'b0);
        end
        assert (irq == |(status_q & intr_en_q));
        if (f_reset_seen) begin
            assert ((data_out_q & ~PINS) == 32'd0);
            assert ((dir_q      & ~PINS) == 32'd0);
            assert ((rise_en_q  & ~PINS) == 32'd0);
            assert ((fall_en_q  & ~PINS) == 32'd0);
            assert ((high_en_q  & ~PINS) == 32'd0);
            assert ((low_en_q   & ~PINS) == 32'd0);
            assert ((intr_en_q  & ~PINS) == 32'd0);
            assert ((status_q   & ~PINS) == 32'd0);
            assert ((in_q       & ~PINS) == 32'd0);
            assert ((in_prev_q  & ~PINS) == 32'd0);
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
