`timescale 1ns / 1ps
`default_nettype none

// Self-checking directed testbench for apb_gpio, lanes N=8 and N=32 on one bus.
module apb_gpio_tb;

    reg         clk     = 1'b0;
    reg         presetn = 1'b0;
    reg  [7:0]  paddr   = 8'h00;
    reg         psel    = 1'b0;
    reg         penable = 1'b0;
    reg         pwrite  = 1'b0;
    reg  [31:0] pwdata  = 32'h0;
    reg  [3:0]  pstrb   = 4'h0;
    reg  [7:0]  gin8    = 8'h00;
    reg  [31:0] gin32   = 32'h0;

    wire [31:0] prdata8;
    wire [31:0] prdata32;
    wire        pready8;
    wire        pready32;
    wire        pslverr8;
    wire        pslverr32;
    wire [7:0]  gout8;
    wire [7:0]  goe8;
    wire [31:0] gout32;
    wire [31:0] goe32;
    wire        irq8;
    wire        irq32;

    apb_gpio #(.ADDR_WIDTH(8), .N(8)) u_n8 (
        .pclk(clk), .presetn(presetn), .paddr(paddr), .psel(psel),
        .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
        .prdata(prdata8), .pready(pready8), .pslverr(pslverr8),
        .gpio_in(gin8), .gpio_out(gout8), .gpio_oe(goe8), .irq(irq8)
    );

    apb_gpio #(.ADDR_WIDTH(8), .N(32)) u_n32 (
        .pclk(clk), .presetn(presetn), .paddr(paddr), .psel(psel),
        .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
        .prdata(prdata32), .pready(pready32), .pslverr(pslverr32),
        .gpio_in(gin32), .gpio_out(gout32), .gpio_oe(goe32), .irq(irq32)
    );

    always #5 clk = ~clk;

    integer        passed = 0;
    integer        failed = 0;
    integer        tstep  = 0;
    reg [8*64-1:0] nonce;
    reg [31:0]     rd8;
    reg [31:0]     rd32;
    reg            err8;
    reg            err32;
    reg [7:0]      a_iter;

    // ------------------------------------------------------------------
    // Checking
    // ------------------------------------------------------------------
    task chk(input [31:0] got_v, input [31:0] exp_v);
        begin
            if (got_v === exp_v) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("apb_gpio_tb: step %0d check %0d: got 0x%08h, expected 0x%08h",
                       tstep, passed + failed, got_v, exp_v);
            end
        end
    endtask

    task chk_bit(input got_b, input exp_b);
        begin
            chk({31'd0, got_b}, {31'd0, exp_b});
        end
    endtask

    task chk_irq(input e8, input e32);
        begin
            chk_bit(irq8, e8);
            chk_bit(irq32, e32);
        end
    endtask

    task chk_outputs_zero;
        begin
            chk({24'd0, gout8}, 32'h0);
            chk({24'd0, goe8}, 32'h0);
            chk(gout32, 32'h0);
            chk(goe32, 32'h0);
            chk_irq(1'b0, 1'b0);
        end
    endtask

    // ------------------------------------------------------------------
    // APB manager
    // ------------------------------------------------------------------
    task apb_xfer(input wr_i, input [7:0] addr_i, input [31:0] data_i, input [3:0] strb_i);
        begin
            @(negedge clk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = wr_i;
            paddr   = addr_i;
            pwdata  = wr_i ? data_i : 32'h0;
            pstrb   = wr_i ? strb_i : 4'h0;
            #1;
            chk(prdata8, 32'h0);
            chk(prdata32, 32'h0);
            chk_bit(pslverr8, 1'b0);
            chk_bit(pslverr32, 1'b0);
            @(negedge clk);
            penable = 1'b1;
            #1;
            chk_bit(pready8, 1'b1);
            chk_bit(pready32, 1'b1);
            rd8   = prdata8;
            rd32  = prdata32;
            err8  = pslverr8;
            err32 = pslverr32;
            @(negedge clk);
            psel    = 1'b0;
            penable = 1'b0;
            pwrite  = 1'b0;
            paddr   = 8'h00;
            pwdata  = 32'h0;
            pstrb   = 4'h0;
            #1;
            chk(prdata8, 32'h0);
            chk(prdata32, 32'h0);
            chk_bit(pslverr8, 1'b0);
            chk_bit(pslverr32, 1'b0);
        end
    endtask

    task apb_write(input [7:0] addr_i, input [31:0] data_i, input [3:0] strb_i, input exp_err);
        begin
            apb_xfer(1'b1, addr_i, data_i, strb_i);
            chk_bit(err8, exp_err);
            chk_bit(err32, exp_err);
        end
    endtask

    task apb_read(input [7:0] addr_i, input [31:0] exp8, input [31:0] exp32, input exp_err);
        begin
            apb_xfer(1'b0, addr_i, 32'h0, 4'h0);
            chk(rd8, exp8);
            chk(rd32, exp32);
            chk_bit(err8, exp_err);
            chk_bit(err32, exp_err);
        end
    endtask

    task read_all_zero;
        begin
            a_iter = 8'h00;
            repeat (9) begin
                apb_read(a_iter, 32'h0, 32'h0, 1'b0);
                a_iter = a_iter + 8'h04;
            end
        end
    endtask

    task test_rw(input [7:0] addr_i);
        begin
            apb_write(addr_i, 32'hFFFF_FFFF, 4'hF, 1'b0);
            apb_read (addr_i, 32'h0000_00FF, 32'hFFFF_FFFF, 1'b0);
            apb_write(addr_i, 32'h0000_0000, 4'b1010, 1'b0);
            apb_read (addr_i, 32'h0000_00FF, 32'h00FF_00FF, 1'b0);
            apb_write(addr_i, 32'h5A5A_5A5A, 4'b0001, 1'b0);
            apb_read (addr_i, 32'h0000_005A, 32'h00FF_005A, 1'b0);
            apb_write(addr_i, 32'hFFFF_FFFF, 4'b0010, 1'b0);
            apb_read (addr_i, 32'h0000_005A, 32'h00FF_FF5A, 1'b0);
            apb_write(addr_i, 32'h0000_0000, 4'hF, 1'b0);
            apb_read (addr_i, 32'h0000_0000, 32'h0000_0000, 1'b0);
        end
    endtask

    task idle_bus;
        begin
            psel    = 1'b0;
            penable = 1'b0;
            pwrite  = 1'b0;
            paddr   = 8'h00;
            pwdata  = 32'h0;
            pstrb   = 4'h0;
        end
    endtask

    // ------------------------------------------------------------------
    // Watchdog
    // ------------------------------------------------------------------
    initial begin
        #2000000;
        failed = failed + 1;
        $error("apb_gpio_tb: timeout");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    // ------------------------------------------------------------------
    // Test sequence
    // ------------------------------------------------------------------
    initial begin
        nonce = {480'd0, "none"};
        if ($value$plusargs("nirmaan_nonce=%s", nonce)) begin
            tstep = 0;
        end

        // 1. Reset values
        tstep   = 1;
        presetn = 1'b0;
        repeat (3) @(posedge clk);
        #1;
        chk_outputs_zero;
        @(negedge clk);
        presetn = 1'b1;
        read_all_zero;
        chk_outputs_zero;

        // 2. Read/write registers, partial strobes, bits above N
        tstep = 2;
        test_rw(8'h00);
        test_rw(8'h04);
        test_rw(8'h0C);
        test_rw(8'h10);
        test_rw(8'h14);
        test_rw(8'h18);
        test_rw(8'h1C);
        // INTR_LOW test set status bits (pins low); clear them all
        apb_write(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
        apb_read (8'h20, 32'h0, 32'h0, 1'b0);
        chk_irq(1'b0, 1'b0);

        // 3. gpio_out and gpio_oe
        tstep = 3;
        apb_write(8'h00, 32'hC3C3_C3C3, 4'hF, 1'b0);
        chk({24'd0, gout8}, 32'h0000_00C3);
        chk(gout32, 32'hC3C3_C3C3);
        chk({24'd0, goe8}, 32'h0);
        chk(goe32, 32'h0);
        apb_write(8'h04, 32'h0F0F_0F0F, 4'b0101, 1'b0);
        chk({24'd0, goe8}, 32'h0000_000F);
        chk(goe32, 32'h000F_000F);
        apb_read (8'h04, 32'h0000_000F, 32'h000F_000F, 1'b0);
        apb_write(8'h00, 32'h0, 4'hF, 1'b0);
        apb_write(8'h04, 32'h0, 4'hF, 1'b0);
        chk_outputs_zero;

        // 4. DATA_IN, read only, one-edge sample latency
        tstep = 4;
        @(negedge clk);
        gin8  = 8'hA5;
        gin32 = 32'hDEAD_BEEF;
        apb_read (8'h08, 32'h0000_00A5, 32'hDEAD_BEEF, 1'b0);
        apb_write(8'h08, 32'h0000_0000, 4'hF, 1'b1);
        apb_write(8'h08, 32'hFFFF_FFFF, 4'b0011, 1'b1);
        apb_read (8'h08, 32'h0000_00A5, 32'hDEAD_BEEF, 1'b0);
        // Pin change during an access phase: old value still read
        @(negedge clk);
        psel = 1'b1; penable = 1'b0; pwrite = 1'b0; paddr = 8'h08; pstrb = 4'h0;
        @(negedge clk);
        penable = 1'b1;
        gin8  = 8'h3C;
        gin32 = 32'h1234_5678;
        #1;
        chk(prdata8, 32'h0000_00A5);
        chk(prdata32, 32'hDEAD_BEEF);
        @(negedge clk);
        idle_bus;
        // Pin change before edge E reads after E
        @(negedge clk);
        gin8  = 8'h5A;
        gin32 = 32'hCAFE_F00D;
        psel = 1'b1; penable = 1'b0; pwrite = 1'b0; paddr = 8'h08; pstrb = 4'h0;
        @(negedge clk);
        penable = 1'b1;
        #1;
        chk(prdata8, 32'h0000_005A);
        chk(prdata32, 32'hCAFE_F00D);
        chk_bit(pslverr8, 1'b0);
        chk_bit(pslverr32, 1'b0);
        @(negedge clk);
        idle_bus;

        // 5. PSLVERR policy and unmapped addresses
        tstep = 5;
        apb_write(8'h24, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_read (8'h24, 32'h0, 32'h0, 1'b1);
        apb_write(8'h01, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_read (8'h01, 32'h0, 32'h0, 1'b1);
        apb_read (8'h02, 32'h0, 32'h0, 1'b1);
        apb_read (8'h03, 32'h0, 32'h0, 1'b1);
        apb_write(8'h05, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_write(8'h40, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_read (8'h40, 32'h0, 32'h0, 1'b1);
        apb_write(8'h44, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_write(8'h80, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_read (8'h80, 32'h0, 32'h0, 1'b1);
        apb_read (8'h3C, 32'h0, 32'h0, 1'b1);
        apb_read (8'h60, 32'h0, 32'h0, 1'b1);
        apb_read (8'hFC, 32'h0, 32'h0, 1'b1);
        apb_write(8'h21, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_read (8'h00, 32'h0, 32'h0, 1'b0);
        apb_read (8'h04, 32'h0, 32'h0, 1'b0);
        apb_read (8'h08, 32'h0000_005A, 32'hCAFE_F00D, 1'b0);
        apb_read (8'h20, 32'h0, 32'h0, 1'b0);
        chk_outputs_zero;

        // Quiet the pins before detection tests
        @(negedge clk);
        gin8  = 8'h00;
        gin32 = 32'h0;
        repeat (3) @(negedge clk);
        apb_read (8'h20, 32'h0, 32'h0, 1'b0);

        // 6. Rising edge: two-edge latency, fires once, partial W1C
        tstep = 6;
        apb_write(8'h1C, 32'hFFFF_FFFF, 4'hF, 1'b0);
        apb_write(8'h0C, 32'h8000_0001, 4'hF, 1'b0);
        apb_read (8'h0C, 32'h0000_0001, 32'h8000_0001, 1'b0);
        chk_irq(1'b0, 1'b0);
        @(negedge clk);
        gin8  = 8'h01;
        gin32 = 32'h8000_0001;
        @(negedge clk);
        #1;
        chk_irq(1'b0, 1'b0);
        @(negedge clk);
        #1;
        chk_irq(1'b1, 1'b1);
        repeat (3) @(negedge clk);
        #1;
        chk_irq(1'b1, 1'b1);
        apb_read (8'h20, 32'h0000_0001, 32'h8000_0001, 1'b0);
        apb_write(8'h20, 32'h0000_0001, 4'hF, 1'b0);
        apb_read (8'h20, 32'h0, 32'h8000_0000, 1'b0);
        chk_irq(1'b0, 1'b1);
        apb_write(8'h20, 32'h8000_0000, 4'b0111, 1'b0);
        apb_read (8'h20, 32'h0, 32'h8000_0000, 1'b0);
        apb_write(8'h20, 32'h8000_0000, 4'b1000, 1'b0);
        apb_read (8'h20, 32'h0, 32'h0, 1'b0);
        chk_irq(1'b0, 1'b0);
        repeat (4) @(negedge clk);
        #1;
        chk_irq(1'b0, 1'b0);
        apb_read (8'h20, 32'h0, 32'h0, 1'b0);
        apb_write(8'h0C, 32'h0, 4'hF, 1'b0);

        // 7. Falling edge on pin 1
        tstep = 7;
        apb_write(8'h10, 32'h0000_0002, 4'hF, 1'b0);
        @(negedge clk);
        gin8  = 8'h03;
        gin32 = 32'h8000_0003;
        repeat (3) @(negedge clk);
        #1;
        chk_irq(1'b0, 1'b0);
        @(negedge clk);
        gin8  = 8'h01;
        gin32 = 32'h8000_0001;
        @(negedge clk);
        #1;
        chk_irq(1'b0, 1'b0);
        @(negedge clk);
        #1;
        chk_irq(1'b1, 1'b1);
        apb_read (8'h20, 32'h0000_0002, 32'h0000_0002, 1'b0);
        apb_write(8'h20, 32'h0000_0002, 4'hF, 1'b0);
        apb_read (8'h20, 32'h0, 32'h0, 1'b0);
        repeat (3) @(negedge clk);
        #1;
        chk_irq(1'b0, 1'b0);
        apb_write(8'h10, 32'h0, 4'hF, 1'b0);

        // 8. High level on pin 2: a clear does not stick while it holds
        tstep = 8;
        apb_write(8'h14, 32'h0000_0004, 4'hF, 1'b0);
        @(negedge clk);
        gin8  = 8'h05;
        gin32 = 32'h8000_0005;
        @(negedge clk);
        #1;
        chk_irq(1'b0, 1'b0);
        @(negedge clk);
        #1;
        chk_irq(1'b1, 1'b1);
        apb_read (8'h20, 32'h0000_0004, 32'h0000_0004, 1'b0);
        apb_write(8'h20, 32'h0000_0004, 4'hF, 1'b0);
        apb_read (8'h20, 32'h0000_0004, 32'h0000_0004, 1'b0);
        chk_irq(1'b1, 1'b1);
        @(negedge clk);
        gin8  = 8'h01;
        gin32 = 32'h8000_0001;
        repeat (2) @(negedge clk);
        apb_write(8'h20, 32'h0000_0004, 4'hF, 1'b0);
        apb_read (8'h20, 32'h0, 32'h0, 1'b0);
        chk_irq(1'b0, 1'b0);
        apb_write(8'h14, 32'h0, 4'hF, 1'b0);

        // 9. Low level on pin 3
        tstep = 9;
        apb_write(8'h18, 32'h0000_0008, 4'hF, 1'b0);
        apb_read (8'h20, 32'h0000_0008, 32'h0000_0008, 1'b0);
        chk_irq(1'b1, 1'b1);
        apb_write(8'h20, 32'h0000_0008, 4'hF, 1'b0);
        apb_read (8'h20, 32'h0000_0008, 32'h0000_0008, 1'b0);
        @(negedge clk);
        gin8  = 8'h09;
        gin32 = 32'h8000_0009;
        repeat (2) @(negedge clk);
        apb_write(8'h20, 32'h0000_0008, 4'hF, 1'b0);
        apb_read (8'h20, 32'h0, 32'h0, 1'b0);
        chk_irq(1'b0, 1'b0);
        apb_write(8'h18, 32'h0, 4'hF, 1'b0);

        // 10. Masked conditions still set status; partial W1C with strobes; mask
        tstep = 10;
        apb_write(8'h1C, 32'h0, 4'hF, 1'b0);
        @(negedge clk);
        gin8  = 8'h00;
        gin32 = 32'h0;
        repeat (3) @(negedge clk);
        apb_write(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
        apb_read (8'h20, 32'h0, 32'h0, 1'b0);
        apb_write(8'h0C, 32'hFFFF_FFFF, 4'hF, 1'b0);
        @(negedge clk);
        gin8  = 8'hFF;
        gin32 = 32'hFFFF_FFFF;
        repeat (3) @(negedge clk);
        apb_read (8'h20, 32'h0000_00FF, 32'hFFFF_FFFF, 1'b0);
        chk_irq(1'b0, 1'b0);
        apb_write(8'h0C, 32'h0, 4'hF, 1'b0);
        apb_write(8'h20, 32'h0000_0F05, 4'b0001, 1'b0);
        apb_read (8'h20, 32'h0000_00FA, 32'hFFFF_FFFA, 1'b0);
        apb_write(8'h20, 32'hFF00_0000, 4'b0111, 1'b0);
        apb_read (8'h20, 32'h0000_00FA, 32'hFFFF_FFFA, 1'b0);
        apb_write(8'h20, 32'hF0F0_F0F0, 4'hF, 1'b0);
        apb_read (8'h20, 32'h0000_000A, 32'h0F0F_0F0A, 1'b0);
        apb_write(8'h1C, 32'h0000_0005, 4'hF, 1'b0);
        chk_irq(1'b0, 1'b0);
        apb_write(8'h1C, 32'h0000_0002, 4'hF, 1'b0);
        chk_irq(1'b1, 1'b1);
        apb_write(8'h1C, 32'h0100_0000, 4'hF, 1'b0);
        chk_irq(1'b0, 1'b1);
        apb_read (8'h1C, 32'h0, 32'h0100_0000, 1'b0);
        apb_write(8'h1C, 32'h0, 4'hF, 1'b0);
        chk_irq(1'b0, 1'b0);
        apb_write(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
        apb_read (8'h20, 32'h0, 32'h0, 1'b0);

        // 11. Clear on the very edge a new rising edge is detected
        tstep = 11;
        @(negedge clk);
        gin8  = 8'h00;
        gin32 = 32'h0;
        repeat (3) @(negedge clk);
        apb_write(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
        apb_write(8'h0C, 32'h0000_0010, 4'hF, 1'b0);
        @(negedge clk);
        gin8  = 8'h10;
        gin32 = 32'h0000_0010;
        repeat (3) @(negedge clk);
        @(negedge clk);
        gin8  = 8'h00;
        gin32 = 32'h0;
        repeat (3) @(negedge clk);
        apb_read (8'h20, 32'h0000_0010, 32'h0000_0010, 1'b0);
        // pin rises before edge E; clear's access phase ends on E+1,
        // the same edge on which the detection sets the status
        @(negedge clk);
        gin8  = 8'h10;
        gin32 = 32'h0000_0010;
        psel = 1'b1; penable = 1'b0; pwrite = 1'b1; paddr = 8'h20;
        pwdata = 32'h0000_0010; pstrb = 4'hF;
        @(negedge clk);
        penable = 1'b1;
        #1;
        chk_bit(pslverr8, 1'b0);
        chk_bit(pslverr32, 1'b0);
        @(negedge clk);
        idle_bus;
        apb_read (8'h20, 32'h0000_0010, 32'h0000_0010, 1'b0);
        apb_write(8'h20, 32'h0000_0010, 4'hF, 1'b0);
        apb_read (8'h20, 32'h0, 32'h0, 1'b0);
        apb_write(8'h0C, 32'h0, 4'hF, 1'b0);

        // 12. Reset again
        tstep = 12;
        apb_write(8'h00, 32'hFFFF_FFFF, 4'hF, 1'b0);
        apb_write(8'h04, 32'hFFFF_FFFF, 4'hF, 1'b0);
        apb_write(8'h1C, 32'hFFFF_FFFF, 4'hF, 1'b0);
        apb_write(8'h14, 32'hFFFF_FFFF, 4'hF, 1'b0);
        @(negedge clk);
        #1;
        chk({24'd0, gout8}, 32'h0000_00FF);
        chk(goe32, 32'hFFFF_FFFF);
        chk_irq(1'b1, 1'b1);
        @(negedge clk);
        presetn = 1'b0;
        @(posedge clk);
        #1;
        chk_outputs_zero;
        @(negedge clk);
        gin8  = 8'h00;
        gin32 = 32'h0;
        @(negedge clk);
        presetn = 1'b1;
        read_all_zero;
        chk_outputs_zero;

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
